package com.example.cvd;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.annotation.PostConstruct;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@RestController
@RequestMapping("/api/metrology")
public class MetrologyApi {
 static final String STATION="KLA-SIM-01";
 final DataStore db;final Pipeline pipeline;final AccessStore access;final KafkaTemplate<String,String> kafka;final TransactionTemplate tx;final boolean enabled;
 public MetrologyApi(DataStore db,Pipeline pipeline,AccessStore access,KafkaTemplate<String,String> kafka,@Value("${METROLOGY_ENABLED:false}") boolean enabled){this.db=db;this.pipeline=pipeline;this.access=access;this.kafka=kafka;this.enabled=enabled;tx=new TransactionTemplate(new DataSourceTransactionManager(db.pg.getDataSource()));}
 @PostConstruct void init()throws Exception{String sql=new String(getClass().getResourceAsStream("/metrology.sql").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);for(String s:sql.split(";"))if(!s.isBlank())db.pg.execute(s);if(enabled)db.pg.update("INSERT INTO metrology_config(id) VALUES(1) ON CONFLICT DO NOTHING");}
 static String key(String equipment,String wafer,String run){return UUID.nameUUIDFromBytes((equipment+"\n"+wafer+"\n"+run).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 @KafkaListener(topics="cvd.events.v1",groupId="kla-source-evidence")
 void evidence(String raw){if(!enabled)return;JsonNode e=db.parse(raw);String kind=e.path("kind").asText(),eq=e.path("equipmentId").asText(),wafer=e.path("waferId").asText();if(!Equipment.IDS.contains(eq)||wafer.isBlank()||!Set.of("process-result","movement-complete").contains(kind))return;JsonNode p=e.path("payload");String run=p.path("processRunId").asText();if(run.isBlank())return;
  if(!Boolean.TRUE.equals(db.pg.queryForObject("SELECT EXISTS(SELECT 1 FROM metrology_config WHERE id=1 AND enabled_at<=?::timestamptz)",Boolean.class,e.path("sourceTime").asText())))return;
  boolean complete=kind.equals("process-result")&&p.path("complete").asBoolean();boolean returned=kind.equals("movement-complete")&&p.path("to").asText().matches("LP[123]")&&p.path("result").asText().equals("success");if(!complete&&!returned)return;
  tx.executeWithoutResult(t->{db.pg.update("INSERT INTO metrology_evidence(equipment_id,wafer_id,run_id) VALUES(?,?,?) ON CONFLICT DO NOTHING",eq,wafer,run);db.pg.queryForList("SELECT run_id FROM metrology_evidence WHERE equipment_id=? AND wafer_id=? AND run_id=? FOR UPDATE",eq,wafer,run);String column=complete?"completed":"returned";db.pg.update("UPDATE metrology_evidence SET "+column+"=coalesce("+column+",?::jsonb) WHERE equipment_id=? AND wafer_id=? AND run_id=?",raw,eq,wafer,run);var rows=db.pg.queryForList("SELECT completed::text,returned::text FROM metrology_evidence WHERE equipment_id=? AND wafer_id=? AND run_id=? AND completed IS NOT NULL AND returned IS NOT NULL",eq,wafer,run);if(rows.isEmpty())return;var c=db.parse((String)rows.getFirst().get("completed"));var cp=c.path("payload");var s=cp.path("result").deepCopy();if(!(s instanceof ObjectNode source))return;source.put("equipmentId",eq).put("waferId",wafer).put("lotId",c.path("lotId").asText()).put("slot",cp.path("slot").asInt()).put("pm",cp.path("pm").asText()).put("purpose",cp.path("purpose").asText());String k=key(eq,wafer,run);String id=UUID.randomUUID().toString();insert(id,k,1,null,source,null);if(!validSource(source))db.pg.update("UPDATE metrology_runs SET state='awaiting-remeasure',failure_reason='invalid-source' WHERE id=?",id);});
 }
 void insert(String id,String key,int revision,String previous,JsonNode source,String request){db.pg.update("INSERT INTO metrology_runs(id,source_key,revision,previous_id,equipment_id,wafer_id,source,request_key) VALUES(?,?,?,?,?,?,?::jsonb,?) ON CONFLICT DO NOTHING",id,key,revision,previous,source.path("equipmentId").asText(),source.path("waferId").asText(),source.toString(),request);}
 @Scheduled(fixedDelay=1000) void dispatch(){if(!enabled)return;tx.executeWithoutResult(t->{if(!Boolean.TRUE.equals(db.pg.queryForObject("SELECT pg_try_advisory_xact_lock(7302041)",Boolean.class)))return;db.pg.update("UPDATE metrology_runs SET state='in-transit' WHERE state='waiting-transfer'");db.pg.update("UPDATE metrology_runs SET state='queued' WHERE state='in-transit' AND arrival_at<=now()");var rows=db.pg.queryForList("SELECT id,source::text,(last_sent IS NULL OR last_sent<now()-interval '15 seconds') AS ready FROM metrology_runs WHERE state IN ('queued','measuring') ORDER BY arrival_at,queue_seq LIMIT 1 FOR UPDATE SKIP LOCKED");if(rows.isEmpty())return;var r=rows.getFirst();if(!Boolean.TRUE.equals(r.get("ready")))return;try{String id=(String)r.get("id");var body=db.mapper.createObjectNode().put("equipmentId",STATION).put("commandId",id).put("type","measure").put("expiresAt",Instant.now().plusSeconds(60).toString());body.set("parameters",db.mapper.createObjectNode().put("measurementId",id).set("source",db.parse((String)r.get("source"))));kafka.send("cvd.commands.v1",STATION,pipeline.signControl(body.toString())).get(5,java.util.concurrent.TimeUnit.SECONDS);db.pg.update("UPDATE metrology_runs SET last_sent=now() WHERE id=?",id);}catch(Exception ex){throw new IllegalStateException("metrology dispatch unavailable",ex);}});}
 @KafkaListener(topics="metrology.snapshot.v1",groupId="kla-station") void station(String raw){JsonNode n=db.parse(raw);if(!STATION.equals(n.path("equipmentId").asText()))return;db.pg.update("INSERT INTO metrology_station(id,body) VALUES(?,?::jsonb) ON CONFLICT(id) DO UPDATE SET body=excluded.body,received_at=now()",STATION,raw);}
 @KafkaListener(topics="metrology.events.v1",groupId="kla-results") void result(String raw){JsonNode e=db.parse(raw);if(!STATION.equals(e.path("equipmentId").asText())||!e.path("kind").asText().equals("measurement-state"))return;JsonNode p=e.path("payload");String id=p.path("measurementId").asText(),event=e.path("eventId").asText(),state=p.path("state").asText();long seq=e.path("sequence").asLong();if(event.isBlank()||!Set.of("queued","measuring","completed","awaiting-remeasure").contains(state))return;
 tx.executeWithoutResult(t->{var rows=db.pg.queryForList("SELECT source::text,state,source_sequence FROM metrology_runs WHERE id=? FOR UPDATE",id);if(rows.isEmpty())return;if(db.pg.update("INSERT INTO metrology_inbox(id) VALUES(?) ON CONFLICT DO NOTHING",event)==0)return;var row=rows.getFirst();if(Set.of("completed","awaiting-remeasure").contains(row.get("state"))||seq<=((Number)row.get("source_sequence")).longValue())return;JsonNode result=p.path("result");boolean valid=!state.equals("completed")||validResult(result,db.parse((String)row.get("source")));String next=valid?state:"awaiting-remeasure";boolean completed=next.equals("completed");if(next.equals("awaiting-remeasure"))db.pg.update("UPDATE metrology_runs SET failure_reason=? WHERE id=?",valid?"measurement-failed":"invalid-result",id);db.pg.update("UPDATE metrology_runs SET state=?,source_sequence=?,result=?::jsonb,completed_at=CASE WHEN ? THEN now() ELSE completed_at END,alarm=? WHERE id=?",next,seq,completed?result.toString():null,completed,completed&&result.path("quality").asText().equals("review"),id);});
 }
 static boolean validSource(JsonNode s){if(!Equipment.IDS.contains(s.path("equipmentId").asText())||!s.path("pm").asText().matches("PM[1-4]")||s.path("slot").asInt()<1||s.path("slot").asInt()>25)return false;for(String k:List.of("waferId","lotId","processRunId","recipeVersion"))if(s.path(k).asText().isBlank())return false;for(String k:List.of("thicknessNm","targetThicknessNm","thicknessTolerancePct","uniformityLimitPct"))if(!numeric(s,k)||s.path(k).asDouble()<0)return false;if(s.path("targetThicknessNm").asDouble()<=0||!s.path("sampleThicknessNm").isArray()||s.path("sampleThicknessNm").size()!=5)return false;for(JsonNode v:s.path("sampleThicknessNm"))if(!v.isNumber()||!Double.isFinite(v.asDouble())||v.asDouble()<0)return false;return true;}
 static boolean validResult(JsonNode n,JsonNode source){
  if(!validSource(source)||!n.path("seed").asText().matches("[0-9a-f]{64}"))return false;
  if(!n.path("synthetic").asBoolean()||!n.path("modelVersion").asText().equals("synthetic-kla-v1")||n.path("diameterMm").asDouble()!=300||n.path("edgeExclusionMm").asDouble()!=3||!n.path("coordinates").asText().equals("center-x-right-y-up-notch-down-mm")||!n.path("points").isArray()||n.path("points").size()!=49||!n.path("defects").isArray()||n.path("defects").size()>1000)return false;
  for(String k:List.of("equipmentId","waferId","lotId","slot","pm","processRunId","recipeVersion","sampleThicknessNm","thicknessNm","targetThicknessNm","thicknessTolerancePct","uniformityLimitPct"))if(!sameValue(n.path("source").path(k),source.path(k)))return false;
  double sum=0,min=Double.POSITIVE_INFINITY,max=0;boolean review=false;double target=source.path("targetThicknessNm").asDouble(),tol=source.path("thicknessTolerancePct").asDouble();if(target<=0)return false;
  Set<String> coordinates=new HashSet<>();for(JsonNode p:n.path("points")){if(!coordinates.add(p.path("x").asDouble()+","+p.path("y").asDouble())||!point(p)||!numeric(p,"thicknessNm")||p.path("thicknessNm").asDouble()<0)return false;double v=p.path("thicknessNm").asDouble();sum+=v;min=Math.min(min,v);max=Math.max(max,v);review|=Math.abs(v-target)/target*100>tol;}
  double mean=sum/49,uniformity=mean>0?(max-min)/2/mean*100:0;review|=mean==0||uniformity>source.path("uniformityLimitPct").asDouble();if(!close(n,"meanNm",mean)||!close(n,"minNm",min)||!close(n,"maxNm",max)||(mean>0?!close(n,"uniformityPct",uniformity):!n.path("uniformityPct").isNull()))return false;
  boolean defects=n.path("defects").size()>10;Set<String> ids=new HashSet<>();for(JsonNode d:n.path("defects")){if(!point(d)||!numeric(d,"sizeUm")||d.path("sizeUm").asDouble()<0||d.path("defectId").asText().isBlank()||!ids.add(d.path("defectId").asText())||!Set.of("particle","scratch","other").contains(d.path("type").asText()))return false;defects|=d.path("sizeUm").asDouble()>1;if(d.path("type").asText().equals("scratch")){if(!d.path("path").isArray()||d.path("path").size()<2)return false;for(JsonNode p:d.path("path"))if(!point(p))return false;}}
  return n.path("defectCountLimit").asInt()==10&&n.path("defectSizeLimitUm").asDouble()==1&&n.path("thicknessQuality").asText().equals(review?"review":"pass")&&n.path("defectQuality").asText().equals(defects?"review":"pass")&&n.path("quality").asText().equals(review||defects?"review":"pass");
 }
 static boolean sameValue(JsonNode a,JsonNode b){if(a.isNumber()&&b.isNumber())return Double.isFinite(a.asDouble())&&Double.isFinite(b.asDouble())&&a.asDouble()==b.asDouble();if(a.isArray()&&b.isArray()){if(a.size()!=b.size())return false;for(int i=0;i<a.size();i++)if(!sameValue(a.get(i),b.get(i)))return false;return true;}return a.equals(b);}
 static boolean numeric(JsonNode n,String k){return n.path(k).isNumber()&&Double.isFinite(n.path(k).asDouble());}static boolean close(JsonNode n,String k,double v){return numeric(n,k)&&Math.abs(n.path(k).asDouble()-v)<1e-7;}static boolean point(JsonNode p){return numeric(p,"x")&&numeric(p,"y")&&Math.hypot(p.path("x").asDouble(),p.path("y").asDouble())<=147;}
 @GetMapping("/runs") public List<JsonNode> runs(@RequestParam String equipmentId,@RequestParam(defaultValue="") String waferId,@RequestParam(defaultValue="0") int page){Equipment.require(equipmentId);return db.pg.queryForList("SELECT (to_jsonb(r)-'result'-'source')::text FROM metrology_runs r WHERE equipment_id=? AND (?='' OR wafer_id=?) ORDER BY created_at DESC,queue_seq DESC LIMIT 50 OFFSET ?",String.class,equipmentId,waferId,waferId,Math.max(0,Math.min(page,100000))*50).stream().map(db::parse).toList();}
 @GetMapping("/runs/{id}") public JsonNode detail(@PathVariable String id){var rows=db.pg.queryForList("SELECT to_jsonb(r)::text FROM metrology_runs r WHERE id=?",String.class,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return db.parse(rows.getFirst());}
 @GetMapping("/station") public Map<String,Object> status(){var rows=db.pg.queryForList("SELECT body::text,received_at,received_at>now()-interval '10 seconds' AS fresh FROM metrology_station WHERE id=?",STATION);return Map.of("enabled",enabled,"stationId",STATION,"station",rows.isEmpty()?Map.of():rows.getFirst(),"queue",db.pg.queryForList("SELECT state,count(*) count FROM metrology_runs WHERE state NOT IN ('completed','awaiting-remeasure') GROUP BY state"));}
 static void engineer(){if(!Set.of("Engineer","Leader").contains(AccessSessions.actor().role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"需要 Engineer／Leader");}
 @PostMapping("/runs/{id}/remeasure") public Map<String,String> remeasure(@PathVariable String id,@RequestBody Map<String,String> body){engineer();if(!enabled)throw new ResponseStatusException(HttpStatus.CONFLICT,"量測尚未啟用");String request=body.get("requestId");try{UUID.fromString(request);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"invalid requestId");}String requestKey=AccessSessions.actor().id()+"/"+id+"/"+request;
 return tx.execute(t->{var row=detail(id);String tool=row.path("equipment_id").asText();DummyApprovalApi.lock(db,tool);if(Boolean.TRUE.equals(db.pg.queryForObject("SELECT EXISTS(SELECT 1 FROM commands WHERE equipment_id=? AND body->>'type'='resume' AND status IN ('received','accepted'))",Boolean.class,tool)))throw new ResponseStatusException(HttpStatus.CONFLICT,"復機指令待執行，不可替換量測");String key=row.path("source_key").asText();db.pg.queryForList("SELECT id FROM metrology_runs WHERE source_key=? ORDER BY revision FOR UPDATE",key);var old=db.pg.queryForList("SELECT id FROM metrology_runs WHERE request_key=?",String.class,requestKey);if(!old.isEmpty())return Map.of("id",old.getFirst());if(!validSource(row.path("source"))||row.path("expired").asBoolean()||!Set.of("completed","awaiting-remeasure").contains(row.path("state").asText()))throw new ResponseStatusException(HttpStatus.CONFLICT,"量測尚未完成或已過期");Integer rev=db.pg.queryForObject("SELECT max(revision)+1 FROM metrology_runs WHERE source_key=?",Integer.class,key);String next=UUID.randomUUID().toString();insert(next,key,rev,id,row.path("source"),requestKey);access.audit(AccessSessions.actor(),"metrology-remeasure",next,id,key);return Map.of("id",next);});}
 @PostMapping("/runs/{id}/acknowledge") public Map<String,Boolean> acknowledge(@PathVariable String id){engineer();tx.executeWithoutResult(t->{if(db.pg.update("UPDATE metrology_runs SET acknowledged=true WHERE id=? AND alarm=true",id)!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND);access.audit(AccessSessions.actor(),"metrology-alarm-ack",id,"","");});return Map.of("ok",true);}
 @Scheduled(fixedDelay=3600000) void cleanup(){db.pg.update("UPDATE metrology_runs SET result=NULL,expired=true WHERE completed_at<now()-interval '30 days' AND state='completed' AND (NOT alarm OR acknowledged) AND NOT EXISTS(SELECT 1 FROM metrology_runs active WHERE active.source_key=metrology_runs.source_key AND active.state NOT IN ('completed','awaiting-remeasure'))");}
}
